import catalogData from './catalog.json';

// Shape of catalog.json, generated by scripts/sync-catalog.mjs from the RecurPost API docs.

export type CatalogValue = string | number | boolean;

export interface CatalogParam {
  name: string;
  // string, array, url, integer, boolean, date, datetime, email or object
  type: string;
  required?: boolean;
  description: string;
  enum?: CatalogValue[];
  default?: CatalogValue;
  example?: string;
  // Element type of an array param when it is not a string
  items?: 'object' | 'number';
  // The list endpoint the id param comes from, for example "library_list"
  ref?: string;
}

export interface CatalogEndpoint {
  id: string;
  module: string;
  title: string;
  summary: string;
  auth: string;
  legacy: boolean;
  params: CatalogParam[];
}

export interface CatalogModule {
  module: string;
  title: string;
  description: string;
  endpoints: CatalogEndpoint[];
}

export interface Catalog {
  version: number;
  modules: CatalogModule[];
}

export const catalog = catalogData as unknown as Catalog;

const endpointIndex = new Map<string, CatalogEndpoint>();
for (const mod of catalog.modules) {
  for (const endpoint of mod.endpoints) {
    endpointIndex.set(endpoint.id, endpoint);
  }
}

export function findEndpoint(id: string): CatalogEndpoint | undefined {
  return endpointIndex.get(id);
}

export function getEndpoint(id: string): CatalogEndpoint {
  const endpoint = endpointIndex.get(id);
  if (endpoint === undefined) {
    throw new Error(`Unknown RecurPost endpoint "${id}" in the catalog`);
  }
  return endpoint;
}
